/* Block 3 2026-10-29: isolated visual/teaching update.
 * This script runs AFTER the existing app.js. Block 1+2 code and assets remain unchanged. */
(function(){
 "use strict";
 const updated = {"b3-start":"<section class=\"scene-inner b3-scene b3-pro b3p-overview\"><div class=\"b3p-top\"><span>BLOCK 3 · NEW BUSINESS MODELS</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Was müssen Menschen morgen können?</h1><p class=\"b3p-lead\">Fünf Kapitel verbinden neue Organisationsanforderungen mit deiner persönlichen beruflichen Zukunft.</p><div class=\"b3p-content\"><div class=\"b3p-chapter-grid\"><article class=\"b3p-card mint\"><h3>01 · Skills statt Stellen</h3><div>Wie Unternehmen Fähigkeiten erkennen, einsetzen und gezielt weiterentwickeln.</div></article><article class=\"b3p-card blue\"><h3>02 · Generationen</h3><div>Warum Demografie relevant ist – und warum Stereotype selten helfen.</div></article><article class=\"b3p-card mint\"><h3>03 · New Leadership</h3><div>Wie Führung in hybriden, digitalen Teams Orientierung und Verantwortung schafft.</div></article><article class=\"b3p-card blue\"><h3>04 · Frauen & Führung</h3><div>Wie gerechte Karriere- und Beförderungsentscheidungen entstehen.</div></article><article class=\"b3p-card accent\"><h3>05 · Your Future</h3><div>Lebenslauf, Zielstelle, KI-Recruiter und Karriereplan: dein persönliches Career Kit.</div></article></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Wir betrachten Organisationen und Menschen zusammen: Technologie verändert Aufgaben; Kompetenzen und Führung bestimmen die Umsetzung.</span></div></div></section>","b3c1-start":"<section class=\"scene-inner b3-scene b3-pro b3p-cover\"><div class=\"b3p-top\"><span>BLOCK 3 · KAPITEL 1</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Skills statt Stellen</h1><p class=\"b3p-lead\">Nicht nur „Welche Stelle ist frei?“, sondern „Welche Fähigkeiten brauchen wir, um konkrete Probleme zu lösen?“</p><div class=\"b3p-content\"><div class=\"b3p-split b3p-split-photo\"><div><div class=\"b3p-stack\"><article class=\"b3p-card mint\"><span class=\"b3p-card-num\">01</span><h3>Perspektivwechsel</h3><div>Von Jobtiteln und formalen Abschlüssen zu Aufgaben, Skills und nachweisbarer Leistung.</div></article><article class=\"b3p-card blue\"><span class=\"b3p-card-num\">02</span><h3>Skill Gap</h3><div>Welche Fähigkeiten benötigen wir künftig – und welche besitzen wir bereits?</div></article><article class=\"b3p-card accent\"><span class=\"b3p-card-num\">03</span><h3>Personalentscheidung</h3><div>Was sollten wir einstellen, entwickeln, automatisieren oder anders organisieren?</div></article></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Skills ergänzen Rollen und Verantwortung – sie ersetzen Organisationsstrukturen nicht.</span></div></div><figure class=\"b3p-photo\"><img loading=\"eager\" src=\"assets/block3/redesign-skills.webp\" alt=\"Fotorealistische Darstellung von Zusammenarbeit im modernen Arbeitsumfeld\"><figcaption>Kompetenzen entstehen in konkreten Projekten und Teams.</figcaption></figure></div></div></section>","b3c1-definition":"<section class=\"scene-inner b3-scene b3-pro b3p-def\"><div class=\"b3p-top\"><span>KAPITEL 1 · GRUNDLAGEN</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Skill ≠ Kompetenz</h1><p class=\"b3p-lead\">Eine Fähigkeit allein macht noch keine kompetente Handlung. Entscheidend ist, ob sie im jeweiligen Kontext wirksam eingesetzt wird.</p><div class=\"b3p-content\"><div class=\"b3p-competence\"><div class=\"b3p-factor-row\"><div class=\"b3p-factor\"><b>WISSEN</b><span>Was weiß ich?</span></div><div class=\"b3p-factor\"><b>SKILLS</b><span>Was kann ich?</span></div><div class=\"b3p-factor\"><b>ERFAHRUNG</b><span>Was habe ich schon gelöst?</span></div><div class=\"b3p-factor\"><b>HALTUNG</b><span>Wie gehe ich vor?</span></div></div><div class=\"b3p-down\">↓ WIRKSAME ANWENDUNG IN EINER KONKRETEN SITUATION ↓</div><div class=\"b3p-competence-result\"><strong>KOMPETENZ</strong><span>Wissen, Können, Erfahrung und Haltung situationsgerecht verbinden</span></div></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span><b>Beispiel Nutzerforschung:</b> Interviews führen ist ein Skill. Unterschiedliche Kunden verstehen und daraus belastbare Produktentscheidungen ableiten zeigt Kompetenz.</span></div></div></section>","b3c1-contrast":"<section class=\"scene-inner b3-scene b3-pro b3p-contrast\"><div class=\"b3p-top\"><span>KAPITEL 1 · PERSPEKTIVWECHSEL</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Stellenorientiert vs. skillorientiert</h1><p class=\"b3p-lead\">Die Aufgabe ist dieselbe. Unterschiedlich ist, wen ein Unternehmen überhaupt als geeignete Person wahrnimmt.</p><div class=\"b3p-content\"><div class=\"b3p-grid2\"><article class=\"b3p-card blue\"><h3>KLASSISCH: „Digital Product Manager gesucht“</h3><div><p><b>Filter:</b> passender Abschluss, fünf Jahre Erfahrung, identischer Jobtitel.</p><p><b>Möglicher Nachteil:</b> Ein talentierter Quereinsteiger mit hervorragenden Produktprojekten fällt früh aus dem Raster.</p><div class=\"b3p-flowline\">Jobtitel → Lebenslauf-Filter → Einladung</div></div></article><article class=\"b3p-card mint\"><h3>SKILLORIENTIERT: „NovaCare verbessern“</h3><div><p><b>Bedarf:</b> Nutzerinterviews, Priorisierung, Datenanalyse, Stakeholder-Kommunikation.</p><p><b>Prüfung:</b> Welche Bewerbenden können diese Aufgaben mit Arbeitsproben oder Projekten belegen?</p><div class=\"b3p-flowline\">Aufgaben → Fähigkeiten → Nachweise → Auswahl</div></div></article></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Skillorientierung kann neue Talente sichtbar machen. Fachliche Anforderungen, rechtliche Vorgaben und Verantwortung bleiben bestehen.</span></div></div></section>","b3c1-skillsbased":"<section class=\"scene-inner b3-scene b3-pro b3p-hiring\"><div class=\"b3p-top\"><span>KAPITEL 1 · RECRUITING</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Skills-based Hiring: So funktioniert es</h1><p class=\"b3p-lead\">Eine gute Personalauswahl leitet Anforderungen aus realen Aufgaben ab und prüft Fähigkeiten anhand vergleichbarer Nachweise.</p><div class=\"b3p-content\"><div class=\"b3p-hiring-layout\"><div class=\"b3p-hiring-process\"><div class=\"b3p-step\"><b>1</b><div><strong>Aufgabe definieren</strong><span>Was muss die neue Person wirklich leisten?</span></div></div><div class=\"b3p-step\"><b>2</b><div><strong>Skills ableiten</strong><span>Welche Fähigkeiten sind erfolgskritisch?</span></div></div><div class=\"b3p-step\"><b>3</b><div><strong>Nachweise wählen</strong><span>Arbeitsprobe, Projekt, strukturiertes Interview</span></div></div><div class=\"b3p-step\"><b>4</b><div><strong>Fair entscheiden</strong><span>Gleiche Kriterien für alle Bewerbenden</span></div></div></div><figure class=\"b3p-photo\"><img loading=\"eager\" src=\"assets/block3/redesign-hiring.webp\" alt=\"Fotorealistische Darstellung von Zusammenarbeit im modernen Arbeitsumfeld\"><figcaption>Strukturierte Auswahl statt Bauchgefühl</figcaption></figure></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>LinkedIn modellierte 2025 einen potenziell <b>6,1-mal größeren Talentpool</b> für skillbasierte Suche. Das ist eine Modellrechnung, kein garantierter Recruiting-Erfolg.</span></div></div><div class=\"b3p-source\"><a href=\"https://economicgraph.linkedin.com/content/dam/me/economicgraph/en-us/PDF/skills-based-hiring-march-2025.pdf\" target=\"_blank\" rel=\"noopener\">LinkedIn Economic Graph · Skills-Based Hiring (2025) ↗</a></div></section>","b3c1-gap":"<section class=\"scene-inner b3-scene b3-pro b3p-process\"><div class=\"b3p-top\"><span>KAPITEL 1 · TRANSFORMATION</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Warum Skill Gaps Transformation ausbremsen</h1><p class=\"b3p-lead\">Eine neue Technologie führt nicht automatisch zu besseren Ergebnissen. Teams brauchen Fähigkeiten, Prozesse und klare Verantwortung.</p><div class=\"b3p-content\"><div class=\"b3p-split\"><div class=\"b3p-stack\"><article class=\"b3p-card blue\"><h3>IST-Zustand</h3><div>Welche Kompetenzen sind im Unternehmen tatsächlich vorhanden? Wie gut sind sie nachweisbar?</div></article><article class=\"b3p-card mint\"><h3>SOLL-Zustand</h3><div>Welche Kompetenzen verlangen die zukünftigen Produkte, Prozesse und Kundenerwartungen?</div></article><article class=\"b3p-card accent\"><h3>GAP</h3><div>Differenz zwischen Bedarf und Fähigkeiten: Wo entstehen Risiken oder Engpässe?</div></article></div><div class=\"b3p-vertical-flow\"><div>Strategie</div><i>↓</i><div>Neue Aufgaben</div><i>↓</i><div>Skill Gap</div><i>↓</i><div>Recruiting · Lernen · Redesign</div></div></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Priorisiere nach strategischer Bedeutung, Dringlichkeit und der Möglichkeit, Fähigkeiten intern aufzubauen.</span></div></div></section>","b3c1-map":"<section class=\"scene-inner b3-scene b3-pro b3p-process\"><div class=\"b3p-top\"><span>KAPITEL 1 · INSTRUMENT</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Skill-Gap-Analyse in vier Schritten</h1><p class=\"b3p-lead\">Eine strukturierte Analyse vermeidet Maßnahmen nach Bauchgefühl und macht Weiterbildung planbar.</p><div class=\"b3p-content\"><div class=\"b3p-foursteps\"><div class=\"b3p-step\"><b>01</b><div><strong>Geschäftsziel</strong><span>Welche Leistung muss NovaWorks künftig liefern?</span></div></div><div class=\"b3p-step\"><b>02</b><div><strong>Soll-Kompetenzen</strong><span>Welche Skills und Niveaus sind dafür notwendig?</span></div></div><div class=\"b3p-step\"><b>03</b><div><strong>Ist-Kompetenzen</strong><span>Was kann das Team bereits nachweisen?</span></div></div><div class=\"b3p-step\"><b>04</b><div><strong>Maßnahmen</strong><span>Entwicklung, Recruiting, KI-Unterstützung oder Aufgabenumbau</span></div></div></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span><b>Praxisbeispiel:</b> Ein Team soll KI-basierte Kundenservices entwickeln. Es kann Prozesse gut gestalten, hat aber wenig Erfahrung mit Modellrisiken und Datenschutz.</span></div></div></section>","b3c1-decision":"<section class=\"scene-inner b3-scene b3-pro b3p-decisions\"><div class=\"b3p-top\"><span>KAPITEL 1 · MANAGEMENT</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Fünf Wege, Kompetenzlücken zu schließen</h1><p class=\"b3p-lead\">Nicht jede fehlende Fähigkeit erfordert sofort eine Neueinstellung. Die Entscheidung hängt auch von Zeit, Risiko und Entwicklungspotenzial ab.</p><div class=\"b3p-content\"><div class=\"b3p-chapter-grid\"><article class=\"b3p-card mint\"><span class=\"b3p-card-num\">01</span><h3>HIRE</h3><div>Extern geeignete Menschen gewinnen – gut bei dauerhaftem, dringendem Bedarf.</div></article><article class=\"b3p-card blue\"><span class=\"b3p-card-num\">02</span><h3>TRAIN</h3><div>Vorhandene Mitarbeitende qualifizieren – stärkt Bindung und internes Wissen.</div></article><article class=\"b3p-card mint\"><span class=\"b3p-card-num\">03</span><h3>PARTNER</h3><div>Expertise vorübergehend zukaufen – schnell, aber abhängig von Externen.</div></article><article class=\"b3p-card blue\"><span class=\"b3p-card-num\">04</span><h3>AUGMENT</h3><div>KI oder Tools zur Unterstützung einsetzen – nur mit Verantwortung und Kontrolle.</div></article><article class=\"b3p-card accent\"><span class=\"b3p-card-num\">05</span><h3>REDESIGN</h3><div>Aufgaben neu verteilen oder Prozesse verändern – nicht nur Stellen ersetzen.</div></article></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Wähle Maßnahmen nicht isoliert: Oft ist die Kombination aus Weiterbildung, Prozessanpassung und gezieltem Recruiting sinnvoll.</span></div></div></section>","b3c2-intro-bridge":"<section class=\"scene-inner b3-scene b3-pro b3p-cover\"><div class=\"b3p-top\"><span>BLOCK 3 · KAPITEL 2</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Warum sprechen wir über Generationen?</h1><p class=\"b3p-lead\">Demografischer Wandel verändert den Arbeitsmarkt. Doch Geburtsjahrgänge allein erklären nicht, was einzelne Menschen erwarten.</p><div class=\"b3p-content\"><div class=\"b3p-split b3p-split-photo\"><div><div class=\"b3p-stack\"><article class=\"b3p-card mint\"><h3>Demografie</h3><div>Viele Beschäftigte gehen in den Ruhestand, Nachwuchs und Fachkräfte sind regional unterschiedlich verfügbar.</div></article><article class=\"b3p-card blue\"><h3>Erwartungen</h3><div>Lohn, Sicherheit, Entwicklung, Sinn und Vereinbarkeit können in jeder Generation wichtig sein.</div></article><article class=\"b3p-card accent\"><h3>Führungsaufgabe</h3><div>Gute Regeln berücksichtigen Lebensphasen und individuelle Bedürfnisse statt Klischees.</div></article></div></div><figure class=\"b3p-photo\"><img loading=\"eager\" src=\"assets/block3/redesign-people.webp\" alt=\"Fotorealistische Darstellung von Zusammenarbeit im modernen Arbeitsumfeld\"><figcaption>Generationen treffen im Arbeitsalltag aufeinander.</figcaption></figure></div></div></section>","b3c2-est-alpha":"<section class=\"scene-inner b3-scene b3-pro b3p-estimate\"><div class=\"b3p-top\"><span>BLOCK 3 · KAPITEL 2 · SCHÄTZFRAGE</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Wer ist weltweit die größte junge Kohorte?</h1><p class=\"b3p-lead\">Wie hoch war der Anteil der Generation Alpha an der Weltbevölkerung Ende 2024? Schätzt zunächst selbst.</p><div class=\"b3p-content\"><div class=\"b3p-est-layout\"><div class=\"b3p-est-question\"><h3>Deine Schätzung</h3><div class=\"b3p-est-options\"><span>10 %</span><span>15 %</span><span>20 %</span><span>25 %</span></div><p>Was würde ein hoher Anteil junger Menschen für Bildung, Arbeitsmarkt und Konsummärkte bedeuten?</p><details class=\"b3-reveal b3p-reveal\"><summary>Antwort aufdecken</summary><div class=\"b3p-answer\"><strong>ca. 24,4 %</strong><p>Die verwendete UN-basierte Auswertung beziffert den Anteil Ende 2024 auf rund ein Viertel. Generationengrenzen variieren je nach Quelle.</p></div></details></div><div class=\"b3p-alpha-art\"><div class=\"b3p-alpha-rings\"><span>GEN<br>ALPHA</span></div><p>Die Jüngsten sind global sehr zahlreich – in Deutschland sieht die Altersstruktur anders aus.</p></div></div></div><div class=\"b3p-source\">Bezugsgröße: Weltbevölkerung, UN-basierte Auswertung 2024 · Zahlen gerundet.</div></section>","b3c2-demography-compare":"<section class=\"scene-inner b3-scene b3-pro b3p-demography\"><div class=\"b3p-top\"><span>KAPITEL 2 · DEMOGRAFIE IM VERGLEICH</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Deutschland ist älter als die Welt</h1><p class=\"b3p-lead\">Anteil an der Gesamtbevölkerung, gerundet. Zwei Quellen mit teilweise unterschiedlichen Generationengrenzen.</p><div class=\"b3p-content\"><div class=\"b3p-sidebars\"><article class=\"b3p-card blue\"><h3>DEUTSCHLAND · IPSOS 2026</h3><div><div class=\"b3p-bar-list b3p-germany\"><div class=\"b3p-bar-row\"><span>Babyboomer</span><div class=\"b3p-bar-track\"><i style=\"width:89.2%\"></i></div><b>22,3 %</b></div><div class=\"b3p-bar-row\"><span>Generation X</span><div class=\"b3p-bar-track\"><i style=\"width:87.2%\"></i></div><b>21,8 %</b></div><div class=\"b3p-bar-row\"><span>Millennials</span><div class=\"b3p-bar-track\"><i style=\"width:81.2%\"></i></div><b>20,3 %</b></div><div class=\"b3p-bar-row\"><span>Generation Z</span><div class=\"b3p-bar-track\"><i style=\"width:63.6%\"></i></div><b>15,9 %</b></div><div class=\"b3p-bar-row\"><span>Generation Alpha</span><div class=\"b3p-bar-track\"><i style=\"width:52.0%\"></i></div><b>13,0 %</b></div></div></div></article><article class=\"b3p-card mint\"><h3>WELT · UN-BASIERT 2024</h3><div><div class=\"b3p-bar-list b3p-world\"><div class=\"b3p-bar-row\"><span>Babyboomer</span><div class=\"b3p-bar-track\"><i style=\"width:51.2%\"></i></div><b>12,8 %</b></div><div class=\"b3p-bar-row\"><span>Generation X</span><div class=\"b3p-bar-track\"><i style=\"width:66.8%\"></i></div><b>16,7 %</b></div><div class=\"b3p-bar-row\"><span>Millennials</span><div class=\"b3p-bar-track\"><i style=\"width:84.8%\"></i></div><b>21,2 %</b></div><div class=\"b3p-bar-row\"><span>Generation Z</span><div class=\"b3p-bar-track\"><i style=\"width:91.6%\"></i></div><b>22,9 %</b></div><div class=\"b3p-bar-row\"><span>Generation Alpha</span><div class=\"b3p-bar-track\"><i style=\"width:97.6%\"></i></div><b>24,4 %</b></div></div></div></article></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>In Deutschland ist der Anteil von Babyboomern und Gen X höher; weltweit sind Gen Z und Alpha anteilig größer. Das betrifft Nachwuchsgewinnung, Weiterbildung und Altersvorsorge.</span></div></div><div class=\"b3p-source\">Quellen: Ipsos Generations Report 2026; UN-basierte Auswertung 2024. Abweichende Definitionen beachten.</div></section>","b3c2-video":"<section class=\"scene-inner b3-scene b3-pro b3p-videos-slide\"><div class=\"b3p-top\"><span>KAPITEL 2 · VIDEO & DISKUSSION</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Boomer trifft Gen Z: Klischees im Büro</h1><p class=\"b3p-lead\">Zwei humorvolle Perspektiven. Beobachtet: Was ist ein Stereotyp, und was ließe sich wissenschaftlich überprüfen?</p><div class=\"b3p-content\"><div class=\"b3p-videos\"><article><h3>Video 1 · Büro-Klischees</h3><div class=\"b3p-video\"><iframe src=\"https://www.youtube-nocookie.com/embed/_ZQhvfhmybY\" title=\"AgentZ: Das Büro besetzen\" loading=\"lazy\" allow=\"accelerometer; encrypted-media; picture-in-picture\" allowfullscreen></iframe></div><a href=\"https://www.youtube.com/watch?v=_ZQhvfhmybY\" target=\"_blank\" rel=\"noopener\">Video auf YouTube öffnen ↗</a></article><article><h3>Video 2 · Dein zweiter Impuls</h3><div class=\"b3p-video\"><iframe src=\"https://www.youtube-nocookie.com/embed/0GPTj7IeeDw?start=57\" title=\"Boomer und Generation Z – weiteres Video\" loading=\"lazy\" allow=\"accelerometer; encrypted-media; picture-in-picture\" allowfullscreen></iframe></div><a href=\"https://www.youtube.com/watch?v=0GPTj7IeeDw&t=57s\" target=\"_blank\" rel=\"noopener\">Video ab 0:57 öffnen ↗</a></article></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span><b>Diskussion (5 Minuten):</b> Welche Aussagen sind Klischees? Welche Beobachtungen könnten an Führungsstil, Tätigkeit oder Lebensphase statt am Geburtsjahr liegen?</span></div></div></section>","b3c2-start":"<section class=\"scene-inner b3-scene b3-pro b3p-cover\"><div class=\"b3p-top\"><span>BLOCK 3 · KAPITEL 2</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Generationen & neue Karrierebilder</h1><p class=\"b3p-lead\">Was verändert sich wirklich – die Menschen, ihre Lebenssituationen oder die Anforderungen der Arbeitswelt?</p><div class=\"b3p-content\"><div class=\"b3p-split b3p-split-photo\"><div><div class=\"b3p-stack\"><article class=\"b3p-card mint\"><h3>1 · Die Zahlen</h3><div>Wir vergleichen die Altersstrukturen in Deutschland und weltweit.</div></article><article class=\"b3p-card blue\"><h3>2 · Die Motive</h3><div>Wir untersuchen Einkommen, Sinn, Gesundheit und Karriereerwartungen.</div></article><article class=\"b3p-card accent\"><h3>3 · Die Praxis</h3><div>Wir reflektieren Klischees und lösen Konflikte im Generation-Clash-Planspiel.</div></article></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Geburtsjahr ist keine verlässliche Erklärung für individuelles Verhalten. Alter, Lebensphase und Zeitgeist sind auseinanderzuhalten.</span></div></div><figure class=\"b3p-photo\"><img loading=\"eager\" src=\"assets/block3/redesign-people.webp\" alt=\"Fotorealistische Darstellung von Zusammenarbeit im modernen Arbeitsumfeld\"><figcaption>Unterschiedliche Perspektiven brauchen Zusammenarbeit statt Schubladen.</figcaption></figure></div></div></section>","b3c2-data":"<section class=\"scene-inner b3-scene b3-pro b3p-money\"><div class=\"b3p-top\"><span>KAPITEL 2 · DELOITTE 2025</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Money · Meaning · Well-being</h1><p class=\"b3p-lead\">Die Demografie erklärt, wie sich Bevölkerungsgruppen zusammensetzen. Die nächste Frage lautet: <b>Was ist Menschen im Arbeitsleben wichtig?</b></p><div class=\"b3p-content\"><div class=\"b3p-grid3\"><article class=\"b3p-card blue\"><h3>MONEY · Sicherheit</h3><div>Bezahlung, finanzielle Planbarkeit und sichere Perspektiven beeinflussen, ob Beschäftigte bleiben.</div></article><article class=\"b3p-card mint\"><h3>MEANING · Sinn</h3><div>Mitarbeitende möchten verstehen, welchen Beitrag ihre Arbeit leistet und welche Werte das Unternehmen lebt.</div></article><article class=\"b3p-card accent\"><h3>WELL-BEING · Gesundheit</h3><div>Psychische Belastung, Vereinbarkeit und Erholung werden zu konkreten Führungsfragen.</div></article></div><div class=\"b3p-fact-band\"><div><strong>6 %</strong><span>nannten Führung als primäres Karriereziel</span></div><div><strong>89 %</strong><span>Gen Z: Purpose wichtig für Zufriedenheit/Wohlbefinden</span></div><div><strong>92 %</strong><span>Millennials: Purpose wichtig für Zufriedenheit/Wohlbefinden</span></div></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Solche Befragungswerte beschreiben Gruppen, aber keine einzelnen Menschen. Führungsentscheidungen sollten auch individuelle Bedürfnisse berücksichtigen.</span></div></div><div class=\"b3p-source\"><a href=\"https://www.deloitte.com/us/en/insights/topics/talent/2025-gen-z-millennial-survey.html\" target=\"_blank\" rel=\"noopener\">Deloitte Global Gen Z and Millennial Survey 2025 (23.482 Befragte, 44 Länder) ↗</a></div></section>","b3c2-2026":"<section class=\"scene-inner b3-scene b3-pro b3p-careers\"><div class=\"b3p-top\"><span>KAPITEL 2 · KARRIEREVORSTELLUNGEN</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Karriere ist mehr als Hierarchie</h1><p class=\"b3p-lead\">Nicht jede erfolgreiche Laufbahn führt zur disziplinarischen Führung. Unternehmen brauchen unterschiedliche Entwicklungswege.</p><div class=\"b3p-content\"><div class=\"b3p-careerpaths\"><article class=\"b3p-card mint\"><span class=\"b3p-card-num\">1</span><h3>Fachkarriere</h3><div>Expertise ausbauen und komplexe fachliche Entscheidungen treffen.</div></article><article class=\"b3p-card blue\"><span class=\"b3p-card-num\">2</span><h3>Projektkarriere</h3><div>Temporäre Verantwortung für Teams, Lieferergebnisse und Veränderung.</div></article><article class=\"b3p-card accent\"><span class=\"b3p-card-num\">3</span><h3>Führungskarriere</h3><div>Menschen entwickeln, Ziele klären und Entscheidungen verantworten.</div></article></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Diskussion: Welche Karriereangebote sind für unterschiedliche Lebensphasen attraktiv – und welche Vorannahmen sollten Führungskräfte vermeiden?</span></div></div></section>","b3c3-start":"<section class=\"scene-inner b3-scene b3-pro b3p-cover\"><div class=\"b3p-top\"><span>BLOCK 3 · KAPITEL 3</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>New Leadership</h1><p class=\"b3p-lead\">Wenn Menschen räumlich verteilt, digital und selbstorganisiert arbeiten, braucht Führung eine neue Balance.</p><div class=\"b3p-content\"><div class=\"b3p-split b3p-split-photo\"><div><div class=\"b3p-stack\"><article class=\"b3p-card mint\"><h3>ORIENTIERUNG</h3><div>Ziele, Prioritäten und Qualitätsmaßstäbe transparent machen.</div></article><article class=\"b3p-card blue\"><h3>VERTRAUEN</h3><div>Autonomie ermöglichen und zugleich Erreichbarkeit und Unterstützung sichern.</div></article><article class=\"b3p-card accent\"><h3>VERANTWORTUNG</h3><div>Entscheidungen treffen, Konflikte bearbeiten und Ergebnisse nachhalten.</div></article></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Im Planspiel Leadership Inbox entscheidet ihr, wie Führung bei Unsicherheit, Zeitdruck und Zielkonflikten konkret handelt.</span></div></div><figure class=\"b3p-photo\"><img loading=\"eager\" src=\"assets/block3/redesign-leader.webp\" alt=\"Fotorealistische Darstellung von Zusammenarbeit im modernen Arbeitsumfeld\"><figcaption>Führung schafft Rahmenbedingungen für gute Entscheidungen.</figcaption></figure></div></div></section>","b3c3-shift":"<section class=\"scene-inner b3-scene b3-pro b3p-leadership\"><div class=\"b3p-top\"><span>KAPITEL 3 · FÜHRUNGSVERSTÄNDNIS</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Vom Boss zum Coach? Nicht so einfach.</h1><p class=\"b3p-lead\">Moderne Führung verbindet Befähigung mit klarer Verantwortung. Coaching ersetzt weder Priorisierung noch schwierige Entscheidungen.</p><div class=\"b3p-content\"><div class=\"b3p-grid2\"><article class=\"b3p-card blue\"><h3>KLASSISCHER IMPULS</h3><div><p>Direkte Anweisung, enge Kontrolle, Entscheidung an der Spitze.</p><p><b>Risiko:</b> Eigeninitiative und Lernen können gebremst werden.</p></div></article><article class=\"b3p-card mint\"><h3>MODERNER IMPULS</h3><div><p>Orientierung und Autonomie, regelmäßiges Feedback, gemeinsame Problemlösung.</p><p><b>Risiko:</b> Ohne Rollen und Leitplanken entstehen Unklarheit und Überlastung.</p></div></article></div><div class=\"b3p-leadership-flow\"><div><b>ZIEL</b><span>Wozu?</span></div><div><b>RAHMEN</b><span>Was ist erlaubt?</span></div><div><b>AUTONOMIE</b><span>Wer entscheidet?</span></div><div><b>FEEDBACK</b><span>Was lernen wir?</span></div></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Wirksam ist nicht maximal viel oder wenig Führung, sondern die zur Situation passende Kombination.</span></div></div></section>","b3c3-manager":"<section class=\"scene-inner b3-scene b3-pro b3p-leaderimpact\"><div class=\"b3p-top\"><span>KAPITEL 3 · FÜHRUNGSWIRKUNG</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>Führung verändert den Arbeitsalltag</h1><p class=\"b3p-lead\">Führungskräfte beeinflussen, wie klar Aufgaben sind, wie sicher Probleme angesprochen werden können und wie Lernen funktioniert.</p><div class=\"b3p-content\"><div class=\"b3p-hiring-layout\"><div class=\"b3p-stack\"><article class=\"b3p-card mint\"><h3>Klarheit schaffen</h3><div>Was ist heute wichtiger als gestern? Welche Ergebnisse erwarten wir?</div></article><article class=\"b3p-card blue\"><h3>Psychologische Sicherheit</h3><div>Fehler, Zweifel und Konflikte ansprechbar machen – ohne Folgen zu verharmlosen.</div></article><article class=\"b3p-card accent\"><h3>Entwicklung ermöglichen</h3><div>Stärken erkennen, Feedback geben und Lernzeit einplanen.</div></article></div><figure class=\"b3p-photo\"><img loading=\"eager\" src=\"assets/block3/redesign-leader.webp\" alt=\"Fotorealistische Darstellung von Zusammenarbeit im modernen Arbeitsumfeld\"><figcaption>Führung bedeutet Entscheidungen und Kommunikation im Team.</figcaption></figure></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Engagement entsteht nicht durch eine Einzelmaßnahme, sondern aus guter Arbeitsgestaltung, verlässlichen Regeln und Führungsverhalten.</span></div></div></section>","b3c3-inbox":"<section class=\"scene-inner b3-scene b3-pro b3p-inbox\"><div class=\"b3p-top\"><span>KAPITEL 3 · PLANSPIEL</span><span class=\"b3p-revision\">NEUDESIGN · 29.10.2026</span></div><h1>The Leadership Inbox</h1><p class=\"b3p-lead\">Ihr führt ein hybrides Team. Innerhalb weniger Minuten treffen mehrere dringende Nachrichten ein – jede Entscheidung hat Nebenfolgen.</p><div class=\"b3p-content\"><div class=\"b3p-split\"><div class=\"b3p-stack\"><article class=\"b3p-card mint\"><h3>ENTSCHEIDEN</h3><div>Welche Nachricht ist kritisch? Welche Aufgabe lässt sich delegieren?</div></article><article class=\"b3p-card blue\"><h3>BEGRÜNDEN</h3><div>Welche Werte, Risiken und Informationen beeinflussen eure Wahl?</div></article><article class=\"b3p-card accent\"><h3>NACHHALTEN</h3><div>Wie informiert ihr das Team? Wann überprüft ihr die Wirkung?</div></article></div><div class=\"b3p-inbox-art\"><div>POSTEINGANG <b>05</b></div><p>Teamkonflikt</p><p>Kundeneskalation</p><p>Überlastung</p><p>KI-Fehler</p><p>Projektverzug</p><small>Welche Antwort kommt zuerst?</small></div></div><div class=\"b3p-takeaway\"><strong>MERKE</strong><span>Im anschließenden Planspiel bearbeitet ihr die fünf konkreten Nachrichten und vergleicht eure Priorisierung.</span></div></div></section>"};
 if(typeof scenes === "undefined" || !Array.isArray(scenes)){console.error("Block3 Update: scenes unavailable");return;}
 const root = document.getElementById("app");
 if(!root){console.error("Block3 Update: #app unavailable");return;}
 let changed=0;
 for(const [id,markup] of Object.entries(updated)){
   const i=scenes.findIndex(x=>x.id===id);
   const el=root.children[i];
   if(i<0 || !el){console.warn("Block3: missing scene",id);continue;}
   const tpl=document.createElement("template");tpl.innerHTML=markup.trim();
   const fresh=tpl.content.firstElementChild;
   if(!fresh) continue;
   const wasActive=el.classList.contains("active");
   el.className=fresh.className+" scene"+(wasActive?" active":"");
   el.innerHTML=fresh.innerHTML;
   el.dataset.index=String(i);
   scenes[i].html=markup;
   changed++;
 }
 // Keep existing tasks, quizzes, and case work, but give all untouched Block 3 ch.1-3 scenes a cohesive visual treatment.
 scenes.forEach((scene,i)=>{
   if(!/^b3(?:c[123]|x[123])/.test(scene.id) || updated[scene.id]) return;
   const el=root.children[i];if(!el) return;
   el.classList.add("b3p-support");
   if(/^b3(?:c1|x1)/.test(scene.id))el.classList.add("b3p-ch1");
   if(/^b3(?:c2|x2)/.test(scene.id))el.classList.add("b3p-ch2");
   if(/^b3(?:c3|x3)/.test(scene.id))el.classList.add("b3p-ch3");
   el.querySelectorAll(".b3-human-photo-strip").forEach(n=>n.remove());
 });
 // Chapter 5 was removed previously. Rename the remaining Your Future chapter in visible slides / navigation, never in Block 2.
 scenes.forEach((scene,i)=>{
   if(!/^b3(?:c6|x6)/.test(scene.id))return;
   const el=root.children[i];if(!el)return;
   const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);
   while(walker.nextNode()){const t=walker.currentNode;t.nodeValue=t.nodeValue.replace(/(KAPITEL|Kapitel)\s*6\b/g,"$1 5");}
 });
 const nav=document.getElementById("drawerNav");
 if(nav){const bg=[...nav.querySelectorAll(".nav-group")].find(g=>g.querySelector(".nav-group-head")?.textContent.includes("BLOCK 3"));
   if(bg)bg.querySelectorAll(".nav-chapter").forEach(c=>{const h=c.querySelector(".nav-chapter-head span");if(!h)return;
     if(/Kapitel\s*5.*(?:Organisationen|Change)/i.test(h.textContent))c.style.display="none";
     if(/Kapitel\s*6.*(?:YOUR FUTURE|Your Future)/i.test(h.textContent))h.textContent="Kapitel 5 · YOUR FUTURE";
   });
 }
 // A visible, permanent production check in Block 3 only.
 window.__BLOCK3_REDESIGN__={version:"2026-10-29-final-3",replaced:changed,expected:Object.keys(updated).length};
 console.info("Block3 redesign installed:",window.__BLOCK3_REDESIGN__);
})();


